from dataclasses import dataclass, replace

@dataclass(frozen=True)
class ThreatAwareSystem:
    system_id: str
    threats: tuple[Threat, ...]

    def filtered(self, predicate: Callable[[Threat], bool]) -> "ThreatAwareSystem":
        return replace(self, threats=tuple(t for t in self.threats if predicate(t)))

